 edge('tank-pump','M105 470 L141 470','suction');edge('pump-p','M209 470 L390 470','pressure');edge('p-hoist','M390 470 L475 470','pressure');edge('hoist-check','M498 395 L620 395 L620 330 L639 330','pressure');edge('check-head','M691 330 L900 330','pressure');edge('head-cyl','M900 330 L917 283','pressure');edge('cyl-rod','M917 317 L900 455 L852 455','return');edge('rod-hoist','M768 455 L544 435','return');edge('hoist-t','M544 467 L544 535 L105 535 L105 510','return');edge('t-tank','M544 535 L105 535','return');edge('hoist-rod','M544 395 L768 395','pressure');edge('rod-cyl','M852 395 L917 317','pressure');edge('cyl-head','M917 283 L900 330 L852 425','return');edge('head-control','M900 330 L852 425','return');edge('control-t','M768 425 L544 435','return');edge('work-ls','M700 330 L700 255 L300 255','pilot');edge('ls-pump','M300 255 L175 255 L175 436','pilot');edge('rod-pilot','M700 395 L700 505 L810 505','pilot');edge('pilot-control','M810 505 L810 467','pilot');edge('float-pilot','M475 395 L475 320','pilot');edge('head-hoist-t','M917 283 L900 330 L544 330 L544 467','return');edge('rod-hoist-t','M917 317 L900 455 L544 455 L544 467','return');edge('load-check','M691 330 L900 330','pressure');edge('ls-standby','M475 360 L300 255','pilot');tp(355,470,'P');tp(735,330,'A');tp(720,395,'B');tp(300,255,'LS');note(40,65,350,'NO ES OEM','Representa la función: fuente, mando, retención de carga y descenso controlado.');note(415,65,350,'LECTURA','Raise: P→Head y Rod→T. Lower: P→Rod y Head→T mediante control de carga.');note(790,65,365,'TERRENO','Antes de intervenir: sostener tolva, descargar presión y verificar energía cero.');
