 txt(35,35,'DIRECCIÓN HIDROSTÁTICA · PRIORIDAD + HMU + LS','section','start');tank(55,430);pump(160,470,'Bomba',true);priority(285,420,'Prioridad');hmu(460,405,'HMU');counterbalance(660,335,'Alivios cruzados');cyl(900,280,'Cilindro L');cyl(900,430,'Cilindro R');
